/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { E, Pow, Sym, add, fn, integrate, log, manualintegrate, mul, pow } from '../../src';
import { sympyStr } from '../sympy-str';

describe("doctests of sympy.integrals.manualintegrate", () => {
  it("integrate(1/x)", () => {
    const x = new Sym('x');
    const v1 = x;
    expect(sympyStr(integrate(pow(x, -1), v1, undefined, { conds: 'piecewise' }))).toBe('log(x)');
  });
  it("integrate(log(x))", () => {
    const x = new Sym('x');
    const v1 = x;
    expect(sympyStr(integrate(log(x), v1, undefined, { conds: 'piecewise' }))).toBe('x*log(x) - x');
  });
  it("integrate(exp(x) / (1 + exp(2 * x)))", () => {
    const x = new Sym('x');
    const v1 = x;
    expect(sympyStr(integrate(mul(pow(add(1, new Pow(E, mul(2, x))), -1), new Pow(E, x)), v1, undefined, { conds: 'piecewise' }))).toBe('RootSum(4*_z**2 + 1, Lambda(_i, _i*log(2*_i + exp(x))))');
  });
  it("integrate(cos(x)**4 * sin(x), x)", () => {
    const x = new Sym('x');
    expect(sympyStr(integrate(mul(pow(fn('cos', [x]), 4), fn('sin', [x])), x, undefined, { conds: 'piecewise' }))).toBe('-cos(x)**5/5');
  });
  it("integrate(cos(x)**4 * sin(x)**3, x)", () => {
    const x = new Sym('x');
    expect(sympyStr(integrate(mul(pow(fn('cos', [x]), 4), pow(fn('sin', [x]), 3)), x, undefined, { conds: 'piecewise' }))).toBe('cos(x)**7/7 - cos(x)**5/5');
  });
  it("integrate(tan(x), x)", () => {
    const x = new Sym('x');
    expect(sympyStr(integrate(fn('tan', [x], { evaluate: false }), x, undefined, { conds: 'piecewise' }))).toBe('-log(cos(x))');
  });
  it("manualintegrate(1 / x, x)", () => {
    const x = new Sym('x');
    expect(sympyStr(manualintegrate(pow(x, -1), x))).toBe('log(x)');
  });
  it("manualintegrate(log(x), x)", () => {
    const x = new Sym('x');
    expect(sympyStr(manualintegrate(log(x), x))).toBe('x*log(x) - x');
  });
  it("manualintegrate(exp(x) / (1 + exp(2 * x)), x)", () => {
    const x = new Sym('x');
    expect(sympyStr(manualintegrate(mul(pow(add(1, new Pow(E, mul(2, x))), -1), new Pow(E, x)), x))).toBe('atan(exp(x))');
  });
  it("manualintegrate(cos(x)**4 * sin(x), x)", () => {
    const x = new Sym('x');
    expect(sympyStr(manualintegrate(mul(pow(fn('cos', [x]), 4), fn('sin', [x])), x))).toBe('-cos(x)**5/5');
  });
  it("manualintegrate(cos(x)**4 * sin(x)**3, x)", () => {
    const x = new Sym('x');
    expect(sympyStr(manualintegrate(mul(pow(fn('cos', [x]), 4), pow(fn('sin', [x]), 3)), x))).toBe('cos(x)**7/7 - cos(x)**5/5');
  });
  it("manualintegrate(tan(x), x)", () => {
    const x = new Sym('x');
    expect(sympyStr(manualintegrate(fn('tan', [x], { evaluate: false }), x))).toBe('-log(cos(x))');
  });
});
